package io.github.diodeme.ji.relay.protocol;

import com.southernstorm.noise.protocol.DHState;
import com.southernstorm.noise.protocol.Noise;
import java.security.GeneralSecurityException;
import java.util.Arrays;

/** X25519 static identity material consumed by the fixed Stage 5 Noise suite. */
public final class NoiseKeyPair implements AutoCloseable {
    private final byte[] privateKey;
    private final byte[] publicKey;

    private NoiseKeyPair(byte[] privateKey, byte[] publicKey) {
        if (privateKey.length != 32 || publicKey.length != 32) {
            throw new IllegalArgumentException("Noise X25519 keys must be 32 bytes");
        }
        this.privateKey = privateKey.clone();
        this.publicKey = publicKey.clone();
    }

    public static NoiseKeyPair generate() {
        try {
            DHState state = Noise.createDH("25519");
            try {
                state.generateKeyPair();
                byte[] privateKey = new byte[state.getPrivateKeyLength()];
                byte[] publicKey = new byte[state.getPublicKeyLength()];
                state.getPrivateKey(privateKey, 0);
                state.getPublicKey(publicKey, 0);
                return new NoiseKeyPair(privateKey, publicKey);
            } finally {
                state.destroy();
            }
        } catch (GeneralSecurityException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    public static NoiseKeyPair fromPrivateKey(byte[] privateKey) {
        try {
            DHState state = Noise.createDH("25519");
            try {
                state.setPrivateKey(privateKey, 0);
                byte[] publicKey = new byte[state.getPublicKeyLength()];
                state.getPublicKey(publicKey, 0);
                return new NoiseKeyPair(privateKey, publicKey);
            } finally {
                state.destroy();
            }
        } catch (GeneralSecurityException failure) {
            throw new IllegalArgumentException("invalid Noise X25519 private key", failure);
        }
    }

    byte[] privateKey() { return privateKey.clone(); }
    public byte[] publicKey() { return publicKey.clone(); }

    @Override public void close() { Arrays.fill(privateKey, (byte) 0); }
}
